using System.Text.Json;
using System.Text.Json.Nodes;
namespace DarkColony.Original;
public sealed class CampaignProgress {
 public static JsonObject Read(string path,string campaign="taar"){if(!File.Exists(path))return campaign!="taar"?new(){["campaign"]=campaign,["completed"]=new JsonObject()}:new(){["completed"]=new JsonObject()};var n=SaveCodec.Open(path)["payload"]!.AsObject();if(n["completed"] is not JsonObject completed||n.Count!=(campaign!="taar"?2:1)||campaign!="taar"&&n["campaign"]?.GetValue<string>()!=campaign)throw new InvalidDataException("Invalid campaign record");
  foreach(var pair in completed){if(!int.TryParse(pair.Key,out int parsed)||parsed<0||parsed>=OriginalCampaign.SupportedCount(campaign)||pair.Key!=parsed.ToString(System.Globalization.CultureInfo.InvariantCulture)||pair.Value is not JsonObject record||record.Count!=3||!Guid.TryParseExact(record["runId"]?.GetValue<string>(),"N",out _))throw new InvalidDataException("Invalid campaign completion");
   int index=int.Parse(pair.Key);foreach(string field in new[]{"entry","profile"}){var p=record[field]!.Deserialize<OriginalProfileContext>(new JsonSerializerOptions{IncludeFields=true,UnmappedMemberHandling=System.Text.Json.Serialization.JsonUnmappedMemberHandling.Disallow})!;if(p.CampaignId!=campaign||p.CampaignIndex!=index+(field=="profile"?1:0)||p.Rank<0||p.Rank>3||p.PromotionScore<0||p.CommanderKills<0||p.Medals.Length!=6)throw new InvalidDataException("Invalid campaign profile");}}
  return n;}
 public static bool Complete(string path,OriginalMission mission){if(!mission.AtOutcome||mission.Outcome is not {Success:true}||mission.ResultProfile==null)return false;var progress=Read(path,mission.CampaignId);var completed=progress["completed"]!.AsObject();string key=mission.CampaignIndex.ToString(System.Globalization.CultureInfo.InvariantCulture);if(completed.ContainsKey(key))return false;completed[key]=new JsonObject{["runId"]=mission.RunId,["entry"]=new SaveCodec(mission.World.Data).Node(mission.World.Session.Profile??new OriginalProfileContext(mission.CampaignIndex,0,0,OriginalCampaign.IsHuman(mission.CampaignId)?Enumerable.Repeat(-1,4).ToArray():new int[4],"Direct mission entry"){CampaignId=mission.CampaignId}),["profile"]=new SaveCodec(mission.World.Data).Node(mission.ResultProfile)};SaveCodec.Write(path,progress);return true;}
 public static OriginalProfileContext? Entry(string path,int index,string campaign="taar"){if(index==0)return null;var completed=Read(path,campaign)["completed"]!;return (completed[(index-1).ToString()]?["profile"]??completed[index.ToString()]?["entry"])?.Deserialize<OriginalProfileContext>(new System.Text.Json.JsonSerializerOptions{IncludeFields=true});}
}
